import{z as k,x as l,o as n,c as B,q as s,j as A,D as e,d as a,s as t,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Grok-2 / Grok-3 公开信息","description":"","frontmatter":{"title":"Grok-2 / Grok-3 公开信息","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/grok-2-3.md","filePath":"llm/grok-2-3.md","lastUpdated":1791063341000}'),p={name:"llm/grok-2-3.md"};function h(G,r,d,m,D,c){const E=l("Mermaid");return n(),B("div",null,[r[2]||(r[2]=s('<h1 id="grok-2-grok-3-公开信息" tabindex="-1">Grok-2 / Grok-3 公开信息 <a class="header-anchor" href="#grok-2-grok-3-公开信息" aria-label="Permalink to &quot;Grok-2 / Grok-3 公开信息&quot;">​</a></h1><div class="epigraph"><p>Grok-3（Think）用大规模强化学习打磨思维链：它学会在解题时回溯纠错、简化步骤，并把预训练里的知识用到推理过程里。</p><footer>—— xAI，Grok 3 Beta — The Age of Reasoning Agents，2025 年 2 月</footer></div><p>Grok-1 的结构表是开源检查点给的；从 Grok-1.5 起，xAI 改走产品博客与演示。<strong>专家个数、层数、是否仍为 8 选 2，公开文本里没有与 Grok-1 同等级的表</strong>，正确句子是「公开信息有限」，不要用 <a href="/llm/grok-1">Grok-1</a> 的规格去填空。本篇只整理 1.5、2、3 三代里能核对的能力声明：长上下文、视觉、Arena 化名、Flux 生图、Think / DeepSearch、训练算力量级。评测分随快照与采样协议变，引用必须写清是否 consensus@64 一类重复采样。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开源 Grok-1 停在 2023 年 10 月的基座，窗口按 README 为 8k 量级，且不会对话。产品要追上同期闭源助手，必须补三块：更长上下文、多模态、以及后来整个行业都在做的测试时推理。xAI 的公开策略是发博客和榜，不发架构论文。读者的任务因此变成：<strong>把「能做什么」与「内部长什么样」分开</strong>。能做什么有日期和产品名；内部长什么样，除算力口号外几乎空白。</p><p>另一条轴是平台。Grok 绑在 X / grok.com 的实时信息与订阅档位上，API 后至。把聊天产品、API 模型 ID、开源权重当成同一检查点，会把安全事件、生图过滤和基准分数搅在一起。</p><h3 id="代际是产品名-不是开源版本号" tabindex="-1">代际是产品名，不是开源版本号 <a class="header-anchor" href="#代际是产品名-不是开源版本号" aria-label="Permalink to &quot;代际是产品名，不是开源版本号&quot;">​</a></h3><p>2024 年 3 月 28 日的 Grok-1.5：强调推理，上下文 <strong>128k</strong>，针检索在该长度上宣称完美取回；相对 Grok-1 的窗口大约 16 倍。随后的 Grok-1.5V 把视觉理解接进同一产品线。2024 年 8 月 13 日的 <strong>Grok-2 / Grok-2 mini</strong>：博客称为相对 1.5 的聊天、代码与推理跃迁；早期版本以 LMSYS 化名 <code>sus-column-r</code> 上榜。视觉理解写进产品能力；图像<strong>生成</strong>则是与 Black Forest Labs 的 <strong>FLUX.1</strong> 合作实验，不是「Grok-2 自己是扩散模型」的证据。2025 年 2 月的 <strong>Grok 3 / Grok 3 mini</strong>：叙事中心换成推理智能体——Think 按钮展开思维链，DeepSearch 作为检索—综合智能体。公开算力口径是相对 Grok-2 <strong>约 10 倍</strong>的训练计算，集群为 Colossus（报道中的加速器规模随扩容变化，应以当时官方表述为准，不宜把后续扩容数字写回发布日）。</p><p><span class="marginnote">Grok-2 的层数、是否 MoE、词表是否仍为 131k，公开信息有限。Grok-3 同样没有结构表。文中出现的 128k / 131k 窗口若来自 1.5 博客或后来 API 定价页，要标明来源，不能默认三代共用同一窗口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>能写进「方法」的，其实是<strong>产品能力如何被训练与露出</strong>，而不是网络图。</p><p>Grok-1.5 的方法声明很短：在 1 的开源快照所代表的进度之后，加强推理，并把上下文拉到 128k；NIAH 作为验收。更细的课程（分几档加长、RoPE 基数、是否 YaRN）没有公开。Grok-2 的方法声明是「核心推理 + 可操纵性 + 工具使用」，并写改进了基于检索内容的推理（识别缺失信息、事件顺序、丢掉无关帖子）。生图走外部 FLUX.1，多模态理解另有预告。这些句子描述的是后训练与工具环，不是新注意力公式。</p><h3 id="think、deepsearch-与-mini" tabindex="-1">Think、DeepSearch 与 Mini <a class="header-anchor" href="#think、deepsearch-与-mini" aria-label="Permalink to &quot;Think、DeepSearch 与 Mini&quot;">​</a></h3><p>Grok 3 博客把 Think 写成：用大规模 RL 打磨思维链，使模型会回溯、纠错、简化步骤；用户可检查思维过程而不只看最终答案。这与后来行业里的「推理模型」同一类对象，但 RL 算法、奖励是过程监督还是结果监督、思维是否在权重里与直答融合，公开信息有限。DeepSearch 被定位为第一代智能体：在网页与 X 语料上检索、处理冲突事实、输出带轨迹的摘要，对标的是深度研究产品而不是单次搜索框。Grok 3 mini 是速度与质量折中的同胞。部分产品界面还有更高算力档的称呼（媒体所称 Big Brain 一类），官方博客正文以 Think / DeepSearch / mini 为准；未在博客里定义的档位不要写成架构分支。</p><p><span class="marginnote">术语翻译：「测试时推理」指答题时多花计算来想，而不是把答案一次性吐出来。Think 按钮就是让模型先在草稿纸上写一堆中间步骤，发现错了就划掉重来（回溯），最后才交答案——用更多时间和 token 换正确率。</span></p>',15)),(n(),A(i,null,{default:e(()=>[t(E,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%5B%22Grok-1%20%E5%BC%80%E6%BA%90%E5%9F%BA%E5%BA%A7%208k%22%5D%20--%3E%20G15%5B%22Grok-1.5%EF%BC%9A128k%20%2B%20%E6%8E%A8%E7%90%86%22%5D%0A%20%20G15%20--%3E%20G15V%5B%22Grok-1.5V%EF%BC%9A%E8%A7%86%E8%A7%89%22%5D%0A%20%20G15%20--%3E%20G2%5B%22Grok-2%20%2F%20mini%EF%BC%9A%E8%81%8A%E5%A4%A9%E4%BB%A3%E7%A0%81%E6%8E%A8%E7%90%86%22%5D%0A%20%20G2%20--%3E%20FLUX%5B%22FLUX.1%20%E7%94%9F%E5%9B%BE%EF%BC%88%E5%90%88%E4%BD%9C%EF%BC%89%22%5D%0A%20%20G2%20--%3E%20G3%5B%22Grok-3%EF%BC%9A%E7%BA%A6%2010%C3%97%20%E8%AE%AD%E7%BB%83%E7%AE%97%E5%8A%9B%22%5D%0A%20%20G3%20--%3E%20TH%5B%22Think%EF%BC%9ARL%20%E6%80%9D%E7%BB%B4%E9%93%BE%22%5D%0A%20%20G3%20--%3E%20DS%5B%22DeepSearch%EF%BC%9A%E6%A3%80%E7%B4%A2%E6%99%BA%E8%83%BD%E4%BD%93%22%5D%0A%20%20G3%20--%3E%20MINI%5B%22Grok-3%20mini%22%5D%0A"})]),fallback:e(()=>[...r[0]||(r[0]=[a(" Loading... ",-1)])]),_:1})),r[3]||(r[3]=o("p",null,"API 在 2025 年 4 月左右对 Grok 3 开放，公开定价页出现过约 13 万 token 上下文量级与按百万 token 计费；具体价与模型别名会变，集成应钉当时文档。权重是否按「发布后约半年开源」的口头时间表放出，应以实际仓库为准，在未出现与 Grok-1 同等级的结构表之前，不得假设 3 的内部仍是 8 专家。",-1)),r[4]||(r[4]=o("p",null,[o("span",{class:"marginnote"},[a("Arena 化名与正式名的对应是营销与评测协议问题。"),o("code",null,"sus-column-r"),a(" 只能说明「当时那份快照在那张榜上的位置」，不能还原温度、系统提示和是否联网。")])],-1)),r[5]||(r[5]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),r[6]||(r[6]=o("p",null,"从机制上能说的只有产品露出的那一层。128k 窗口把可条件化的检索片段与对话历史拉长；没有公开注意力实现，就不能写是稠密全注意力还是稀疏。Think 把部分测试时算力从「采样 64 次再投票」改成「显式思维 token」——二者都可以抬基准，但不是同一件事。xAI 在 Grok 3 数学基准上用过 consensus@64 与直出对比，外部批评指出对照模型的采样协议必须一致；读图时要把协议当作分数的一部分。",-1)),(n(),A(i,null,{default:e(()=>[t(E,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E9%81%93%E6%95%B0%E5%AD%A6%E9%A2%98%22%5D%20--%3E%20A%5B%22%E8%B7%AF%E7%BA%BF%E4%B8%80%EF%BC%9Aconsensus%4064%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E8%B7%AF%E7%BA%BF%E4%BA%8C%EF%BC%9AThink%20%E6%80%9D%E7%BB%B4%E9%93%BE%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E5%90%8C%E4%B8%80%E6%A8%A1%E5%9E%8B%E9%87%8D%E5%A4%8D%E9%87%87%E6%A0%B7%2064%20%E6%AC%A1%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E6%8A%95%E7%A5%A8%E5%8F%96%E5%A4%9A%E6%95%B0%E7%AD%94%E6%A1%88%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%B1%95%E5%BC%80%E6%98%BE%E5%BC%8F%E6%80%9D%E7%BB%B4%20token%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%9B%9E%E6%BA%AF%E3%80%81%E7%BA%A0%E9%94%99%E3%80%81%E7%AE%80%E5%8C%96%E6%AD%A5%E9%AA%A4%22%5D%0A%20%20B2%20--%3E%20B3%5B%22%E7%BB%99%E5%87%BA%E7%AD%94%E6%A1%88%20%2B%20%E5%8F%AF%E6%A3%80%E6%9F%A5%E7%9A%84%E8%BF%87%E7%A8%8B%22%5D%0A%20%20A2%20--%3E%20C%5B%22%E9%83%BD%E8%83%BD%E6%8A%AC%E5%88%86%EF%BC%8C%E4%BD%86%E8%8A%B1%E7%9A%84%E7%AE%97%E5%8A%9B%E4%B8%8E%E5%8F%AF%E8%A7%A3%E9%87%8A%E6%80%A7%E4%B8%8D%E5%90%8C%22%5D%0A%20%20B3%20--%3E%20C%0A"})]),fallback:e(()=>[...r[1]||(r[1]=[a(" Loading... ",-1)])]),_:1})),r[7]||(r[7]=s('<p><span class="marginnote">常见误区：看到「consensus@64 得 90 分」就当成模型一次答对率。它其实是同一道题问 64 次、投票取多数，相当于用约 64 倍算力换稳定。拿这个分数去比「直出一次」的模型，而两边协议不一致，排名就没有意义。</span></p><p>DeepSearch 的机制是环境环：查询 → 检索 → 阅读 → 再查询 → 写报告。质量上限首先是检索器与时间预算，其次才是基座是否 MoE。实时 X 信息是产品差异，也是事实性风险：时间线噪声会被一本正经地综合。FLUX.1 生图与语言模型解耦，安全过滤、人像策略属于图像栈，不能用文本拒答表代替。</p><p><span class="marginnote">把 DeepSearch 想象成一个会自己上网的实习生：接到问题后反复「搜索—读网页—发现说法冲突再搜—整理成报告」。它的水平首先取决于搜索工具好不好、给的时间够不够，其次才是模型本身聪不聪明。</span></p><h3 id="算力口号不是架构" tabindex="-1">算力口号不是架构 <a class="header-anchor" href="#算力口号不是架构" aria-label="Permalink to &quot;算力口号不是架构&quot;">​</a></h3><p>「10 倍于 Grok-2 的训练计算」约束的是 FLOP 预算量级，不揭示稠密还是稀疏、数据是 15T 还是别的。Colossus 解释的是<strong>有足够芯片去花这些 FLOP</strong>，不是一张并行切分图。把 10× 理解成「参数 10 倍」或「专家 10 倍」都没有根据。Grok-1 的 314B 与 25% 激活只描述 2023-10 基座，见 <a href="/llm/grok-moe">Grok MoE</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本篇最重要的边界是：<strong>没有技术报告</strong>。任何层数表、专家表、词表、优化器，若只出现在二手博客，应视为未证实。Grok-2 / 3 的许可是专有产品与 API 条款，与 Grok-1 的 Apache 2.0 不是同一对象。安全与生成内容的争议（包括生图与后来的系统提示改动）属于部署层，不能用来反推网络结构。</p><p>工程上，Think 与 DeepSearch 会把一次用户点击变成许多倍的内部 token 与检索往返；产品必须按订阅档限流。把 Grok-3 当本地权重部署，在官方开源之前没有合法检查点。评测应区分：关闭联网的纯模型、打开 DeepSearch 的智能体、打开 Think 的推理档——三张表混成一句「超过 GPT-4o」没有信息量。</p><p><span class="marginnote">口头上的「未来开源 Grok-2 / 3」不是结构披露。开源当天若仍无 README 规格表，读者的状态与今天相同：只有产品能力，没有可复现的架构。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Grok-1.5（2024-03）公开 128k 上下文与针检索；1.5V 加视觉。Grok-2（2024-08）强调推理与工具，生图走 FLUX.1 合作，早期 Arena 化名为 <code>sus-column-r</code>。</li><li>Grok-3（2025-02）公开 Think（RL 思维链）、DeepSearch 智能体、mini 档，以及相对 Grok-2 约 10× 的训练算力；架构表公开信息有限。</li><li>不得用 Grok-1 的 8 专家 top-2 填 2/3；基准分数必须写清采样协议与是否联网。</li><li>出处：xAI，<em>Announcing Grok-1.5</em>（2024-03-28）；<em>Grok-2 Beta Release</em>（2024-08-13）；<em>Grok 3 Beta</em>（2025-02）。开源结构仅见 <a href="/llm/grok-1">Grok-1</a> 与 <a href="/llm/grok-moe">Grok MoE</a>。</li></ul>',11))])}const F=k(p,[["render",h]]);export{u as __pageData,F as default};
